// 0037 baseline: lawful isolated prefix, never the user's save or an earn-route claim.
test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const pageErrors=new WeakMap<Page,string[]>();
function listen(page:Page){if(pageErrors.has(page))return;const errors:string[]=[];pageErrors.set(page,errors);page.on('pageerror',error=>errors.push(error.message));}
async function database(page:Page){return page.evaluate(()=>new Promise<any>((accept,reject)=>{
 const request=indexedDB.open('chenyuan-playable-v1');request.onupgradeneeded=()=>{request.transaction!.abort();reject(new Error('ART10 readonly observer cannot create a Game database'));};request.onerror=()=>reject(request.error);
 request.onsuccess=()=>{const db=request.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};for(const name of db.objectStoreNames){rows[name]=[];const cursor=tx.objectStore(name).openCursor();cursor.onsuccess=()=>{if(cursor.result){rows[name].push({key:cursor.result.key,value:cursor.result.value});cursor.result.continue();}};}tx.oncomplete=()=>{db.close();accept({version:db.version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};
}));}
function goldenFixture():Game{const d=driver('leave','sword');d.realm();d.realm();d.funds(1000);d.go('sect');validateGame(d.game);return structuredClone(d.game) as Game;}
async function load(page:Page,game:Game,virtual=true,replaceExisting=false){
 listen(page);if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.locator('.app-shell')).toHaveAttribute('data-font-scale','1');let input=page.getByLabel('导入已有存档',{exact:true});let confirmation:string|null=null;
 if(replaceExisting){await expect(page.getByTestId('save-status')).toHaveText('已保存');await page.getByRole('button',{name:'设置',exact:true}).click();input=page.getByTestId('import');}
 await expect(input).toBeEnabled();const initial=await database(page);if(replaceExisting)expect(stateValue(initial,'current')).not.toBeNull();await input.setInputFiles({name:'lawful-art10-golden-prefix.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(game))});if(replaceExisting){await expect(page.getByTestId('game-confirmation-message')).toContainText('导入将替换当前进度。建议先导出备份，再明确确认本次覆盖。');confirmation=await page.getByTestId('game-confirmation-message').innerText();await answerGameConfirmation(page,'import');}await expect(page.getByTestId('action-execution')).toBeVisible();if(replaceExisting)expect(confirmation).toContain('导入将替换当前进度。建议先导出备份，再明确确认本次覆盖。');if(virtual){await expect(page.getByTestId('action-countdown')).toHaveText('0.6 秒');await page.clock.runFor(599);expect(await database(page)).toEqual(initial);await page.clock.runFor(1);}await expect(page.getByTestId('save-status')).toHaveText('已保存');if(replaceExisting&&await page.getByRole('button',{name:'关闭设置',exact:true}).isVisible())await page.getByRole('button',{name:'关闭设置',exact:true}).click();
 const before=await snapshot(page) as Game,expected=structuredClone(game);expected.core.runId=before.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=before.core.runId+':'+expected.core.activeEvent.id;expect(before).toEqual(expected);expect(await activity(page)).toBeNull();return before;
}
async function attach(info:TestInfo,name:string,value:unknown){await info.attach(name,{body:JSON.stringify(value),contentType:'application/json'});}
async function readonlyState(page:Page,game:Game,db:any){expect(await snapshot(page)).toEqual(game);expect(await activitySnapshot(page)).toBeNull();expect(await database(page)).toEqual(db);}

async function running(page:Page,kind:'learn'|'study'|'forge',virtual=true){await expect.poll(async()=>(await activity(page))?.status).toBe('running');const a=await activity(page);expect(a.version).toBe(kind==='forge'?4:5);expect(a.plan.kind).toBe(kind);expect(a.cycleMs).toBe(kind==='learn'?30000:60000);await expect(page.locator('[data-testid=training-activity][data-running=true][data-generation="'+a.generation+'"]')).toBeVisible();if(virtual)await expect(page.getByTestId('training-countdown')).toHaveText((a.cycleMs/1000).toFixed(1)+' 秒');else{const n=parseFloat(await page.getByTestId('training-countdown').innerText());expect(n).toBeGreaterThan(0);expect(n).toBeLessThanOrEqual(a.cycleMs/1000);const live=await activity(page);expect(live.id).toBe(a.id);expect(live.generation).toBe(a.generation);expect(live.nextCommand).toEqual(a.nextCommand);expect(live.status).toBe('running');}return a;}
async function saved(page:Page,a:any,before:Game,accepted:any,info:TestInfo,name:string){
 await expect.poll(async()=>(await activity(page))?.completedCycles).toBe(a.completedCycles+1);await expect(page.getByTestId('save-status')).toHaveText('已保存');const raw=await database(page),after=await snapshot(page) as Game,formal=resolve(before,a.nextCommand),key=a.runId+':'+a.nextCommand.commandId,rows=raw.rows['full-receipts'].filter((r:any)=>r.key===key);expect(raw.version).toBe(9);expect(after).toEqual(formal.nextState);expect(stateValue(raw,'current')).toEqual(after);expect(stateValue(raw,'previous')).toEqual(before);expect(rows).toHaveLength(1);const receipt=rows[0].value;
 const input={kind:'TICK',tick:{commandId:a.nextCommand.commandId,runId:a.runId,expectedRevision:a.gameRevision,activityId:a.id,expectedActivityRevision:a.revision,ownerId:a.ownerId,generation:a.generation}};expect(receipt.format).toBe('chenyuan-activity-receipt');expect(receipt.input).toEqual(input);expect(receipt.fingerprint).toBe(canonicalFingerprint(input));expect(receipt.command).toEqual(a.nextCommand);expect(receipt.result).toEqual(formal.result);
 let reconstructionNow:number;
 if([5,6,7].includes(a.version)){expect(receipt.version).toBe(2);expect(Object.keys(receipt).sort()).toEqual(['format','version','input','fingerprint','activity','command','result','proof'].sort());expect(receipt.proof.activityBefore).toEqual(a);expect(receipt.proof.stateAfter).toEqual(after);expect(receipt.proof.resolvedAt).toBeGreaterThanOrEqual(a.dueAt);reconstructionNow=receipt.proof.resolvedAt;}
 else{expect([1,2,3,4]).toContain(a.version);expect(receipt.version).toBe(1);expect(Object.keys(receipt).sort()).toEqual(['format','version','input','fingerprint','activity','command','result'].sort());expect(receipt).not.toHaveProperty('proof');reconstructionNow=receipt.activity.status==='running'?receipt.activity.startedAt:a.dueAt;}
 expect(Number.isSafeInteger(reconstructionNow)).toBe(true);expect(reconstructionNow).toBeGreaterThanOrEqual(a.dueAt);const done=completeActivity(after,a,formal.result,{commandId:a.nextCommand.commandId,now:reconstructionNow});expect(stateValue(raw,'activity')).toEqual(done);expect(await activity(page)).toEqual(done);expect(receipt.activity).toEqual(done);expect(()=>validateActivityReceipt(receipt,after)).not.toThrow();expect(raw.rows['full-receipts'].filter((r:any)=>r.key!==key)).toEqual(accepted.rows['full-receipts']);expect(raw.rows['full-state'].filter((r:any)=>!['current','previous','activity'].includes(r.key))).toEqual(accepted.rows['full-state'].filter((r:any)=>!['current','previous','activity'].includes(r.key)));for(const store of Object.keys(accepted.rows).filter(n=>!['full-state','full-receipts'].includes(n)))expect(raw.rows[store],store).toEqual(accepted.rows[store]);const proof={a,before,accepted,after,formal,done,raw,key,receipt,reconstructionNow,v4StoppedTimeIsOnlyAReconstruction:a.version===4};await attach(info,name+'-complete-formal-game-activity-all-stores',proof);return proof;
}
async function tick(page:Page,a:any,before:Game,info:TestInfo,name:string){const accepted=await database(page),left=a.dueAt-await page.evaluate(()=>Date.now());expect(left).toBeGreaterThan(0);expect(left).toBeLessThanOrEqual(a.cycleMs);await page.clock.fastForward(left-1);expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await noArrival(page);await page.clock.fastForward(1);return saved(page,a,before,accepted,info,name);}
async function noArrival(page:Page){for(const id of ['jade-arrival','relic-result','configuration-arrival'])await expect(page.getByTestId(id)).toHaveCount(0);}
async function paint(page:Page,id:string){await expect.poll(async()=>{await page.clock.runFor(16);return page.getByTestId(id).isVisible();},{timeout:8000}).toBe(true);const seq=await page.getByTestId(id).getAttribute('data-sequence');expect(Number(seq)).toBeGreaterThan(0);return seq;}
async function observe(page:Page){await page.evaluate(()=>{const w=window as any,rows:any[]=[],seen=new WeakMap<Element,string>();const collect=()=>{for(const n of document.querySelectorAll('[data-testid=jade-arrival],[data-testid=relic-result],[data-testid=configuration-arrival]')){const seq=n.getAttribute('data-sequence')??'';if(seq&&seen.get(n)!==seq){seen.set(n,seq);rows.push({kind:n.getAttribute('data-testid'),sequence:seq,text:n.textContent,wall:Date.now()});}}};const observer=new MutationObserver(collect);observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['data-sequence']});w.__art10Observer=observer;w.__art10Arrivals=rows;});}
async function observed(page:Page){return page.evaluate(()=>(window as any).__art10Arrivals??[]);}
async function quota(page:Page,kind:'cycle'|'start'|'configuration'='cycle'){await page.evaluate(kind=>{const w=window as any,put=IDBObjectStore.prototype.put;w.__art10Rejected=[];w.__art10RestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&(kind==='cycle'?this.name==='full-state'&&key==='current':this.name==='full-receipts'&&(kind==='start'?value?.input?.kind==='START':value?.format==='chenyuan-configuration-receipt'))){w.__art10Rejected.push({key,value:structuredClone(value),wall:Date.now()});w.__art10RestorePut();throw new DOMException('ART10 native '+kind+' quota fixture','QuotaExceededError');}return put.call(this,value,key!);};},kind);}
async function holdWrite(page:Page){await page.evaluate(()=>new Promise<void>((accept,reject)=>{const r=indexedDB.open('chenyuan-playable-v1');r.onerror=()=>reject(r.error);r.onsuccess=()=>{const db=r.result,names=[...db.objectStoreNames],tx=db.transaction(names,'readwrite'),rows:any={};let remaining=names.length,held=true;const w=window as any;w.__art10ReleaseWrite=()=>held=false;const repeat=()=>{const q=tx.objectStore('full-state').get('current');q.onsuccess=()=>{w.__art10HeldGame=q.result;if(held)repeat();};};for(const name of names){rows[name]=[];const q=tx.objectStore(name).openCursor();q.onsuccess=()=>{if(q.result){rows[name].push({key:q.result.key,value:q.result.value});q.result.continue();}else if(--remaining===0){w.__art10HeldDB={version:db.version,rows};repeat();accept();}};}tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error);};};}));}
async function stable(page:Page,proof:any){await page.clock.fastForward(120000);expect(await snapshot(page)).toEqual(proof.after);expect(await database(page)).toEqual(proof.raw);await noArrival(page);}
async function readonlyClick(page:Page,id:string){const before=await snapshot(page),raw=await database(page),a=await activity(page);if(/^(queue-|jade-slot-)/.test(id)||id==='learning-plan-open')await openStudyNotes(page);else await closeStudyNotes(page);await page.getByTestId(id).click();expect(await snapshot(page)).toEqual(before);expect(await activity(page)).toEqual(a);expect(await database(page)).toEqual(raw);}
async function layoutReady(page:Page){await expect.poll(()=>page.evaluate(()=>{const app=document.querySelector<HTMLElement>('.app-shell'),alerts=app?.querySelector('.stage-alerts');if(!app?.classList.contains('immersive-stage')||!alerts)return true;const h=alerts.getBoundingClientRect().height,known=parseFloat(app.style.getPropertyValue('--notice-height'));return Number.isFinite(known)&&Math.abs(known-(h?h+8:0))<=.5;}),{timeout:8000}).toBe(true);}
