  const controls=[...document.querySelectorAll<HTMLElement>(modal?'dialog[open] button,dialog[open] input:not([type=checkbox]),dialog[open] select,dialog[open] summary':'[data-testid=equipment-panel] button,[data-testid=equipment-panel] input:not([type=checkbox]),[data-testid=equipment-panel] select,.game-hud button,.activity-rail button,#primary-navigation button')].filter(visible).map(n=>{const r=box(n),hit=document.elementFromPoint((r.left+r.right)/2,(r.top+r.bottom)/2);return{id:n.getAttribute('data-testid')??n.getAttribute('aria-label')??n.textContent,box:r,inside:r.left>=0&&r.top>=0&&r.right<=innerWidth&&r.bottom<=(modal||n.closest('#primary-navigation')?innerHeight:nav.top),hit:n.matches(':disabled')||!!hit&&(hit===n||n.contains(hit)),clip:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1,parents:parents(n)};});
  const copySelector=modal?'dialog[open] h2,dialog[open] h3,dialog[open] p,dialog[open] label,dialog[open] summary,dialog[open] small':'[data-testid=equipment-panel] h3,.learning-object>p,.learning-facts>small,.learning-slot>span,.learning-slot>strong,.production-budget.primary,.relic-description>p,.relic-current-slot>p,.relic-authorization strong,.learning-plan-summary strong,.preparation-estimate strong,.ta09-queue strong,.ta09-queue small,.ta09-jade-inspect-label,.ta09-jade-inspect-label small,.relic-object-verb,[data-testid=jade-study-status] strong,[data-testid=jade-study-status] small,[data-testid=production-relic-state],[data-testid=relic-result],[data-testid=jade-arrival],[data-testid=configuration-arrival]';
  const copy=[...document.querySelectorAll<HTMLElement>(copySelector)].filter(visible).map(n=>{const b=box(n),range=document.createRange();range.selectNodeContents(n);const lines=[...range.getClientRects()].map(r=>({left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height}));return{text:n.textContent,box:b,font:parseFloat(getComputedStyle(n).fontSize),minimum:n.matches('small,.learning-slot>span,.relic-object-verb,.ta09-jade-inspect-label,[data-testid=jade-arrival],[data-testid=configuration-arrival],.relic-object>strong,.relic-result,.relic-authorization .production-estimate>strong')||n.matches('strong')&&n.parentElement?.matches('.relic-authorization>div')?14:18,clip:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1,lines,linesInside:lines.every(r=>inside(r,b)),parents:parents(n)};});
  const jade=document.querySelector('[data-testid=jade-study-scene]'),expectedArticle=!modal&&!!jade&&visible(jade)&&!!jade.querySelector('.learning-object'),panels=(modal?[]:[...document.querySelectorAll<HTMLElement>('.jade-reading-place .learning-object,.jade-reading-place .jade-readable,.jade-reading-place .learning-facts,.jade-reading-place .learning-slot')]).filter(visible).map(n=>{const b=box(n),c=getComputedStyle(n);return{class:n.className,id:n.getAttribute('data-testid'),kind:n.classList.contains('learning-object')?'article':'section',box:b,inside:b.left>=0&&b.top>=0&&b.right<=innerWidth&&b.bottom<=nav.top,clip:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1,parents:parents(n),computed:{display:c.display,gridRows:c.gridTemplateRows,gridColumns:c.gridTemplateColumns,minHeight:c.minHeight,height:c.height,alignItems:c.alignItems,alignSelf:c.alignSelf}};});const navElement=document.getElementById('primary-navigation')!,navStyle=getComputedStyle(navElement),navLayout={box:box(navElement),display:navStyle.display,flexDirection:navStyle.flexDirection,flex:navStyle.flex,gap:navStyle.gap,width:navStyle.width,height:navStyle.height,border:navStyle.border,buttons:[...navElement.querySelectorAll<HTMLElement>('button')].map(n=>{const c=getComputedStyle(n);return{id:n.dataset.testid,text:n.textContent,box:box(n),flex:c.flex,flexDirection:c.flexDirection,width:c.width,height:c.height,border:c.border,borderWidth:c.borderWidth,font:c.fontSize};})};return{width:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight,controls,copy,expectedArticle,panels,navLayout};
