const stateValue=(raw:any,key:string)=>raw.rows['full-state'].find((r:any)=>r.key===key)?.value??null;
test.afterEach(async({page},info)=>{if(page.isClosed())return;await attach(info,'art10-page-errors',pageErrors.get(page)??[]);expect(pageErrors.get(page)??[]).toEqual([]);await page.evaluate(()=>{const w=window as any;w.__art10ReleaseWrite?.();w.__art10RestorePut?.();w.__art10Observer?.disconnect();});});
async function skills(page:Page,id:string){await openHubFeature(page,'skills');await page.getByTestId('equipment-mode-skills').click();await pickSkill(page,id);}
async function pickSkill(page:Page,id:string){await readonlyClick(page,'learning-library-open');const dialog=page.getByTestId('learning-library-dialog');await expect(dialog).toBeVisible();await dialog.getByLabel('功法流派',{exact:true}).selectOption('all');await dialog.getByLabel('显示后续功法法宝',{exact:true}).check();const pager=dialog.getByRole('navigation',{name:'功法翻页',exact:true});while(await pager.getByTestId('catalogue-prev').isEnabled())await pager.getByTestId('catalogue-prev').click();for(let i=0;i<3&&!await page.getByTestId('skill-select-'+id).isVisible();i++)await pager.getByTestId('catalogue-next').click();await expect(page.getByTestId('skill-select-'+id)).toContainText(C.skills[id].name);await readonlyClick(page,'skill-select-'+id);await expect(dialog).not.toBeVisible();await expect(page.getByTestId('jade-engraving')).toHaveAttribute('data-skill',id);}
async function relic(page:Page,id:string){await openHubFeature(page,'relics');await pickRelic(page,id);}
async function pickRelic(page:Page,id:string){await readonlyClick(page,'relic-library-open');await expect(page.getByTestId('relic-library-dialog')).toBeVisible();await expect(page.getByTestId('forge-'+id)).toContainText(C.relics[id].name);await readonlyClick(page,'forge-'+id);await expect(page.getByTestId('relic-library-dialog')).not.toBeVisible();await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-relic',id);}
async function learningLimits(page:Page,budget?:number,reserve?:number){await readonlyClick(page,'learning-plan-open');await expect(page.getByTestId('learning-plan-dialog')).toBeVisible();if(budget!==undefined)await page.getByLabel('累计研习灵石预算').fill(String(budget));if(reserve!==undefined)await page.getByLabel('研习灵石保留量').fill(String(reserve));}
async function closeLearning(page:Page){if(await page.getByTestId('learning-plan-dialog').isVisible())await readonlyClick(page,'learning-plan-close');}
async function learnPlan(page:Page,ids:string[],budget:number,reserve:number){await skills(page,ids[0]);for(const id of ids){await pickSkill(page,id);await readonlyClick(page,'learn-'+id);}await learningLimits(page,budget,reserve);await closeLearning(page);}
async function forgeLimits(page:Page,limits:{stones?:number;reserve?:number;months?:number;life?:number;items?:Record<string,number>}){await readonlyClick(page,'production-limits');await expect(page.getByRole('dialog')).toContainText('投入限额');for(const [key,label]of [['stones','累计生产灵石预算'],['reserve','生产灵石保留量'],['months','累计生产游戏月预算'],['life','生产余寿保留量']] as const)if(limits[key]!==undefined)await page.getByLabel(label,{exact:true}).fill(String(limits[key]));for(const [id,n]of Object.entries(limits.items??{}))await page.getByLabel(C.items[id].name+'保留量',{exact:true}).fill(String(n));await readonlyClick(page,'production-apply-limits');}
async function begin(page:Page,kind:'learn'|'study'|'forge'){await closeLearning(page);await page.getByTestId(kind==='forge'?'production-start':'preparation-start').click();return running(page,kind);}
function fixture(relicId?:string,options:{owned?:boolean;bound?:boolean;location?:string;learned?:string[];extra?:Record<string,number>}={}):Game{const d=driver('leave','sword');d.realm();d.realm();d.funds(2000);for(const id of options.learned??[]){d.go('sect');d.doAction({type:'LEARN',skill:id});}if(relicId){for(const [item,n]of Object.entries(C.relics[relicId].inputs))d.resource(item,n+(options.extra?.[item]??0));if(options.owned){d.go('cave');d.doAction({type:'FORGE',relic:relicId});if(options.bound)d.doAction({type:'EQUIP_RELIC',relic:relicId});}}d.go(options.location??(relicId?'cave':'sect'));validateGame(d.game);return structuredClone(d.game) as Game;}
async function config(page:Page,action:any,confirm:boolean,info:TestInfo,name:string){const before=await snapshot(page),raw=await database(page),priorActivity=await activity(page);await page.getByTestId(action.type==='EQUIP'?'equip-'+action.skill:'equip-relic-'+action.relic).click();await expect(page.getByTestId('configuration-dialog')).toBeVisible();expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(raw);await frame(page,info,name+'-compare');if(!confirm){await page.getByTestId('configuration-cancel').click();expect(await snapshot(page)).toEqual(before);expect(await activity(page)).toEqual(priorActivity);expect(await database(page)).toEqual(raw);return before;}await page.getByTestId('configuration-confirm').click();await expect(page.getByTestId('configuration-dialog')).not.toBeVisible();await expect(page.getByTestId('action-execution')).toHaveCount(0);await expect.poll(async()=>(await snapshot(page)).core.revision).toBe(before.core.revision+1);const after=await snapshot(page),db=await database(page),rows=db.rows['full-receipts'].filter((r:any)=>!raw.rows['full-receipts'].some((old:any)=>old.key===r.key));expect(rows).toHaveLength(1);const receipt=rows[0].value;expect(receipt.format).toBe('chenyuan-configuration-receipt');expect(receipt.before).toEqual(before);expect(receipt.intent.command).toMatchObject({...action,runId:before.core.runId,expectedRevision:before.core.revision});expect(receipt.intent.expectedActivityId).toBe(priorActivity?.id??null);expect(receipt.intent.expectedActivityRevision).toBe(priorActivity?.revision??null);const formal=resolve(before,receipt.intent.command);expect(after).toEqual(formal.nextState);expect(receipt.after).toEqual(after);expect(receipt.result).toEqual(formal.result);expect(()=>validateConfigurationReceipt(receipt,after)).not.toThrow();const expected=structuredClone(raw);expected.rows['full-state'].find((r:any)=>r.key==='current').value=after;if(priorActivity){const stopped={...priorActivity,revision:priorActivity.revision+1,generation:priorActivity.generation+1,gameRevision:after.core.revision,status:'stopped',nextCommand:null,startedAt:null,dueAt:null,stopReason:{code:'STATE_CHANGED',message:'进度已改变，请重新安排活动；已完成的积累保留'}};expected.rows['full-state'].find((r:any)=>r.key==='activity').value=stopped;expect(await activity(page)).toEqual(stopped);}const previous=expected.rows['full-state'].find((r:any)=>r.key==='previous');if(previous)previous.value=before;else expected.rows['full-state'].push({key:'previous',value:before});expected.rows['full-receipts'].push(rows[0]);for(const n of ['full-state','full-receipts'])expected.rows[n].sort((a:any,b:any)=>a.key<b.key?-1:a.key>b.key?1:0);expect(db).toEqual(expected);await attach(info,name+'-full-instant-configuration',{raw,db,receipt,formal,priorActivity});return after;}
async function viewPlan(page:Page){if(await page.getByTestId('hub-close').isVisible())await readonlyClick(page,'hub-close');await readonlyClick(page,'training-review');}
async function allReadOnly(page:Page,body:()=>Promise<void>){const before=await snapshot(page),raw=await database(page),a=await activity(page);await body();expect(await snapshot(page)).toEqual(before);expect(await activity(page)).toEqual(a);expect(await database(page)).toEqual(raw);}
async function bodyFont(page:Page,selector:string,info:TestInfo,name:string){const rows=await page.locator(selector).evaluateAll(nodes=>nodes.map(n=>{const c=getComputedStyle(n),r=n.getBoundingClientRect();return{selector:n.getAttribute('data-testid'),class:n.className,text:n.textContent,font:parseFloat(c.fontSize),lineHeight:c.lineHeight,backgroundColor:c.backgroundColor,backgroundImage:c.backgroundImage,box:{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height}};}));await attach(info,name+'-actual-body-font',rows);expect(rows).toHaveLength(1);expect(Number.isFinite(rows[0].font)&&rows[0].font>=18).toBe(true);}

async function articleText(page:Page,selector:string,info:TestInfo,name:string){const rows=await page.locator(selector).evaluate(node=>{const inside=(a:any,b:any)=>a.left>=b.left-.5&&a.right<=b.right+.5&&a.top>=b.top-.5&&a.bottom<=b.bottom+.5;return[...node.querySelectorAll<HTMLElement>('h3,p,small')].filter(n=>n.getClientRects().length&&!!n.textContent?.trim()).map(n=>{const b=n.getBoundingClientRect(),range=document.createRange();range.selectNodeContents(n);const lines=[...range.getClientRects()].filter(r=>r.width&&r.height),clips=[] as any[];for(let p=n.parentElement;p;p=p.parentElement){const c=getComputedStyle(p);if(/hidden|clip|auto|scroll/.test(c.overflow+c.overflowX+c.overflowY))clips.push(p.getBoundingClientRect());}return{text:n.textContent,minimum:n.matches('small')?14:18,font:parseFloat(getComputedStyle(n).fontSize),positive:b.width>0&&b.height>0,lines:lines.length,inside:lines.every(r=>inside(r,b)),notClipped:clips.every(c=>lines.every(r=>inside(r,c))),scroll:n.scrollWidth<=n.clientWidth+1&&n.scrollHeight<=n.clientHeight+1};});});await attach(info,name+'-complete-article-text-ranges',rows);expect(rows.length).toBeGreaterThan(0);for(const row of rows){expect(Number.isFinite(row.font)&&row.font>=row.minimum).toBe(true);expect(row.positive).toBe(true);expect(row.lines).toBeGreaterThan(0);expect(row.inside).toBe(true);expect(row.notClipped).toBe(true);expect(row.scroll).toBe(true);}}

