 const readRelics:string[]=[];for(const [id,r]of Object.entries(C.relics)){await relic(page,id);await expect(page.locator('.relic-description h3')).toHaveText(r.name);await expect(page.locator('.relic-description')).toContainText(r.description);await articleText(page,'.relic-description',info,id);await expect(page.getByTestId('relic-library-dialog')).not.toBeVisible();await expect(page.locator('.relic-rack:visible')).toHaveCount(0);await expect(page.getByTestId('relic-inscription-object')).toBeVisible();await readonlyState(page,game,db);readRelics.push(id);}expect(readRelics).toHaveLength(4);await frame(page,info,'all-four-retain-a-single-selected-artifact');await attach(info,'complete-readonly-catalogues',{skills:readSkills,relics:readRelics});

