 await pickSkill(page,ids[1]);await expect(page.getByTestId('jade-engraving')).toHaveAttribute('data-working','false');expect(await activity(page)).toEqual(a);expect(await database(page)).toEqual(accepted);await page.clock.fastForward(a.dueAt-await page.evaluate(()=>Date.now())-1);expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await holdWrite(page);try{await page.clock.fastForward(1);await expect(page.getByTestId('save-status')).toHaveText('保存中');expect(await page.evaluate(()=>(window as any).__art10HeldDB)).toEqual(accepted);await expect(page.getByTestId('jade-engraving')).toHaveAttribute('data-working','false');await expect(page.getByTestId('jade-engraving')).not.toHaveAttribute('data-phase','sealing');await noArrival(page);await frame(page,info,'another-library-scroll-cannot-borrow-current-sealing');}finally{await page.evaluate(()=>(window as any).__art10ReleaseWrite());}const proof=await saved(page,a,before,accepted,info,'first-of-original-four-scrolls');expect(proof.after.learned).toEqual([...before.learned,ids[0]]);expect(proof.after.loadout).toEqual(before.loadout);await noArrival(page);const b=await running(page,'learn');expect(b.plan).toEqual(a.plan);expect(b.nextCommand.skill).toBe(ids[1]);await pickSkill(page,'talisman_calm');await readonlyClick(page,'learn-talisman_calm');await learningLimits(page,888,11);await closeLearning(page);expect(await activity(page)).toEqual(b);await page.getByTestId('training-pause').click();await expect.poll(async()=>(await activity(page)).status).toBe('paused');expect(await snapshot(page)).toEqual(proof.after);
