async function pagedGoalSource(page:Page,id:string){const button=page.getByTestId('go-source-'+id);for(let i=0;i<6&&!await button.isVisible();i++){const next=page.getByTestId('goal-panel').getByRole('navigation',{name:'目标来源翻页',exact:true}).getByTestId('catalogue-next');await expect(next).toBeEnabled();await next.click();}await expect(button).toBeVisible();return button;}

test('ART10-A6 one genuine retained-material gap leads through an explicit source and cave journey back to the nondefault forge plan',async({page},info)=>{
 const before=await load(page,oneMissingMaterialFixture());await relic(page,'jade_seal');await forgeLimits(page,{stones:177,reserve:12,months:9,life:5,items:{jade:1}});await readonlyClick(page,'relic-preparation-open');await expect(page.getByTestId('production-source-jade')).toContainText('保留 1 = 需有 5');await expect(page.getByTestId('production-source-jade')).toContainText('持有 4 · 尚缺 1');const raw=await database(page);await readonlyClick(page,'production-source-jade');await expect(page.getByTestId('target')).toHaveText('筹备'+C.items.jade.name+' ×5');await expect(page.getByTestId('need-jade')).toContainText('4 / 5 · 尚缺 1');expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(raw);await readonlyClick(page,'inspect-jade');await expect(page.getByTestId('source-title')).toContainText(C.items.jade.name);await expect(page.getByTestId('goal-panel')).toContainText('5');expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(raw);const go=await pagedGoalSource(page,'jade_task');await expect(go).toContainText('查看此地');await go.click();expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(raw);await expect(page.getByTestId('source-planner')).toBeVisible();await expect(page.getByTestId('source-jade_task')).toHaveAttribute('aria-pressed','true');await page.getByTestId('source-plan-open').click();await page.getByLabel('取材次数',{exact:true}).selectOption('1');await page.getByTestId('source-plan-close').click();await page.getByTestId('source-start').click();const source=await online(page,'source',90000,2),collected=await tick(page,source,before,info,'one-explicit-jade-task-for-real-gap');expect(collected.after.core.inventory.jade).toBe(5);expect(collected.after.ownedRelics).toEqual(before.ownedRelics);expect(collected.after.loadout).toEqual(before.loadout);
 await openHubFeature(page,'relics');await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-relic','jade_seal');await readonlyClick(page,'production-limits');await expect(page.getByLabel('累计生产灵石预算')).toHaveValue('177');await expect(page.getByLabel('生产灵石保留量')).toHaveValue('12');await expect(page.getByLabel('累计生产游戏月预算')).toHaveValue('9');await expect(page.getByLabel('生产余寿保留量')).toHaveValue('5');await expect(page.getByLabel(C.items.jade.name+'保留量')).toHaveValue('1');await page.getByRole('button',{name:'取消调整',exact:true}).click();await expect(page.getByTestId('production-return-cave')).toBeEnabled();const beforeTravel=await database(page);await page.getByTestId('production-return-cave').click();const travel=await online(page,'travel',6000,6);expect(travel.nextCommand).toMatchObject({type:'TRAVEL',location:'cave'});const arrived=await tick(page,travel,collected.after,info,'explicit-cave-travel-does-not-forge');expect(arrived.after.core.world.location).toBe('cave');expect(arrived.after.ownedRelics).toEqual(before.ownedRelics);expect(arrived.after.loadout).toEqual(before.loadout);expect(arrived.after.core.inventory).toEqual(collected.after.core.inventory);await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-relic','jade_seal');await expect(page.getByTestId('production-start')).toBeEnabled();const a=await begin(page,'forge');expect(a.plan).toEqual({kind:'forge',relicId:'jade_seal',maxCycles:1,stoneBudget:177,stoneReserve:12,monthBudget:9,remainingMonthsReserve:5,itemReserves:{jade:1}});const proof=await tick(page,a,arrived.after,info,'material-preparation-to-one-sixty-second-forge');expect(proof.after.core.inventory.jade).toBe(1);expect(proof.after.core.player.stones).toBe(arrived.after.core.player.stones-140);expect(proof.after.core.world.elapsedMonths).toBe(arrived.after.core.world.elapsedMonths+2);expect(proof.after.ownedRelics).toEqual([...before.ownedRelics,'jade_seal']);expect(proof.after.loadout).toEqual(before.loadout);await frame(page,info,'one-material-one-journey-one-forge-with-explicit-limits');await stable(page,proof);await attach(info,'cross-stage-original-plan-and-travel',{source:collected.receipt,travel:arrived.receipt,forge:proof.receipt,beforeTravel});
});

test('ART10-A7 an owned artifact moves to compare or browse while its complete original forge authorization remains canonical after refresh',async({page},info)=>{
 const before=await load(page,fixture('cloud_mirror',{extra:{jade:2,dew:3}}));await relic(page,'cloud_mirror');await forgeLimits(page,{stones:233,reserve:17,months:9,life:5,items:{jade:2,dew:3}});const a=await begin(page,'forge');expect(a.plan).toEqual({kind:'forge',relicId:'cloud_mirror',maxCycles:1,stoneBudget:233,stoneReserve:17,monthBudget:9,remainingMonthsReserve:5,itemReserves:{jade:2,dew:3}});const proof=await tick(page,a,before,info,'saved-owned-cloud-mirror-complete-budget');expect(proof.after.ownedRelics).toContain('cloud_mirror');expect(proof.after.loadout.relic).toBe(before.loadout.relic);await expect(page.getByTestId('production-start')).toHaveCount(0);await expect(page.getByTestId('equip-relic-cloud_mirror')).toBeEnabled();await config(page,{type:'EQUIP_RELIC',relic:'cloud_mirror'},false,info,'owned-artifact-compare-cancel');expect(await database(page)).toEqual(proof.raw);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await viewPlan(page);await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-relic','cloud_mirror');await expect(page.locator('.relic-authorization')).toContainText('原已保存安排');await readonlyClick(page,'production-limits');await expect(page.getByTestId('forge-original-plan')).toHaveAttribute('data-activity',a.id);await expect(page.getByTestId('forge-original-plan')).toHaveAttribute('data-run',before.core.runId);await expect(page.getByTestId('forge-original-plan')).toContainText('最多 1 件 · 每件 60 秒 · 已完成 1');await expect(page.getByTestId('forge-original-budget')).toHaveText('累计上限 233 灵石 / 9 月 · 保留 17 灵石 / 余寿 5 月');await expect(page.getByTestId('forge-original-spent')).toHaveText('实际已用 160 灵石 / 2 游戏月');await expect(page.getByTestId('forge-original-item-jade')).toContainText('原保留 2 · 实耗 2');await expect(page.getByTestId('forge-original-item-dew')).toContainText('原保留 3 · 实耗 5');await frame(page,info,'canonical-all-forge-budgets-and-two-material-reserves');await page.getByRole('button',{name:'返回器物',exact:true}).click();expect(await snapshot(page)).toEqual(proof.after);expect(await database(page)).toEqual(proof.raw);
 const bound=await config(page,{type:'EQUIP_RELIC',relic:'cloud_mirror'},true,info,'owned-artifact-explicit-bind');expect(bound.loadout.relic).toBe('cloud_mirror');expect(bound.core.player.stones).toBe(proof.after.core.player.stones);expect(bound.core.inventory).toEqual(proof.after.core.inventory);await expect(page.getByTestId('production-start')).toHaveCount(0);await expect(page.getByTestId('equip-relic-cloud_mirror')).toHaveCount(0);await expect(page.getByTestId('relic-library-browse')).toBeEnabled();await frame(page,info,'bound-artifact-fact-and-useful-other-blueprints');const final=await database(page);await readonlyClick(page,'relic-library-browse');await readonlyClick(page,'relic-library-close');await page.clock.fastForward(120000);expect(await snapshot(page)).toEqual(bound);expect(await database(page)).toEqual(final);await noArrival(page);
});

test('ART10-A8 a positive-cost forge START quota keeps its original authorization through readonly catalogues and retries once',async({page},info)=>{
 const before=await load(page,fixture('frost_sword'));await relic(page,'frost_sword');await forgeLimits(page,{stones:177,reserve:12,months:9,life:5,items:{jade:0,core:0}});await observe(page);const accepted=await database(page);await quota(page,'start');await page.getByTestId('production-start').click();await expect(page.getByTestId('error')).toContainText('存储空间不足');const rejected=await page.evaluate(()=>(window as any).__art10Rejected);expect(rejected).toHaveLength(1);const original=rejected[0].value;expect(original.input.kind).toBe('START');expect(original.input.plan).toEqual({kind:'forge',relicId:'frost_sword',maxCycles:1,stoneBudget:177,stoneReserve:12,monthBudget:9,remainingMonthsReserve:5,itemReserves:{jade:0,core:0}});expect(original.activity.nextCommand).toMatchObject({type:'FORGE',relic:'frost_sword',runId:before.core.runId,expectedRevision:before.core.revision});expect(C.relics.frost_sword.stones).toBeGreaterThan(0);expect(Object.values(C.relics.frost_sword.inputs).every(n=>n>0)).toBe(true);expect(original.fingerprint).toBe(canonicalFingerprint(original.input));expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await noArrival(page);await expect(page.getByTestId('production-start')).toBeDisabled();await quotaBlankAlpha(page,info);await frame(page,info,'positive-start-quota-keeps-complete-budget-and-original-intent');await readonlyClick(page,'relic-preparation-open');await frame(page,info,'quota-still-allows-complete-material-reading');await readonlyClick(page,'relic-preparation-close');await pickRelic(page,'cloud_mirror');await pickRelic(page,'frost_sword');expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await expect(page.getByTestId('retry')).toBeEnabled();await page.getByTestId('retry').click();const a=await running(page,'forge'),admission=await database(page),starts=admission.rows['full-receipts'].filter((r:any)=>r.key===rejected[0].key);expect(starts).toHaveLength(1);const admitted=starts[0].value;expect(admitted.input).toEqual(original.input);expect(admitted.fingerprint).toBe(original.fingerprint);expect(admitted.command).toBeNull();expect(admitted.result).toBeNull();const normalized=structuredClone(admitted);normalized.activity.id=original.activity.id;normalized.activity.nextCommand.commandId=original.activity.nextCommand.commandId;expect(normalized).toEqual(original);const formal=createActivity(before,original.input.plan,{id:a.id,ownerId:original.input.mutation.ownerId,commandId:original.input.mutation.commandId,now:original.activity.startedAt});expect(a).toEqual(formal);expect(()=>validateActivityReceipt(admitted,before)).not.toThrow();const expected=structuredClone(accepted),row=expected.rows['full-state'].find((r:any)=>r.key==='activity');if(row)row.value=formal;else expected.rows['full-state'].push({key:'activity',value:formal});expected.rows['full-receipts'].push(starts[0]);for(const name of ['full-state','full-receipts'])expected.rows[name].sort((x:any,y:any)=>x.key<y.key?-1:x.key>y.key?1:0);expect(admission).toEqual(expected);expect(await snapshot(page)).toEqual(before);await noArrival(page);const proof=await tick(page,a,before,info,'positive-start-original-intent-first-paid-forge');expect(proof.after.core.player.stones).toBe(before.core.player.stones-140);expect(proof.after.core.inventory.jade).toBe(before.core.inventory.jade-3);expect(proof.after.core.inventory.core).toBe(before.core.inventory.core-1);expect(proof.after.ownedRelics).toEqual([...before.ownedRelics,'frost_sword']);expect(proof.after.loadout).toEqual(before.loadout);await paint(page,'relic-result');expect((await observed(page)).filter((r:any)=>r.kind==='relic-result')).toHaveLength(1);await frame(page,info,'original-start-first-success-exact-receipt');await attach(info,'start-quota-original-full-payload-and-exact-admission',{original,admitted,formal,accepted,admission});await stable(page,proof);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await relic(page,'frost_sword');expect(await snapshot(page)).toEqual(proof.after);expect(await database(page)).toEqual(proof.raw);await noArrival(page);
});

async function librarySpines(page:Page,info:TestInfo){
 const rows=await page.getByTestId('learning-library-dialog').locator('.learning-entries>button').evaluateAll(nodes=>nodes.map(n=>{const box=(p:Element)=>{const r=p.getBoundingClientRect();return{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height};},spine=n.querySelector('.library-book-spine');if(!spine)return{id:n.getAttribute('data-testid'),hit:box(n),spine:null,paint:null,inside:false};const c=getComputedStyle(spine),b=box(spine),hit=box(n);return{id:n.getAttribute('data-testid'),hit,spine:b,paint:{display:c.display,visibility:c.visibility,opacity:Number(c.opacity),backgroundImage:c.backgroundImage,backgroundColor:c.backgroundColor},inside:b.left>=hit.left-.5&&b.right<=hit.right+.5&&b.top>=hit.top-.5&&b.bottom<=hit.bottom+.5};}));await attach(info,'requested-library-four-real-painted-spines',rows);expect(rows).toHaveLength(4);for(const row of rows){expect(row.spine,'A real painted spine is distinct from its full hit surface: '+row.id).not.toBeNull();expect(row.paint?.display).not.toBe('none');expect(row.paint?.visibility).toBe('visible');expect(row.paint?.opacity).toBeGreaterThan(0);expect(Number.isFinite(row.spine!.width)&&row.spine!.width>=44).toBe(true);expect(row.spine!.width).toBeLessThan(row.hit.width*.75);expect(row.spine!.height).toBeGreaterThan(row.spine!.width);expect(row.inside).toBe(true);expect(row.paint!.backgroundImage!=='none'||!['rgba(0, 0, 0, 0)','transparent'].includes(row.paint!.backgroundColor)).toBe(true);}
}
async function quotaBlankAlpha(page:Page,info:TestInfo){
 const image=page.getByTestId('relic-inscription-object').locator('.relic-cold-blank img');await expect(image).toHaveCount(1);await expect(image).toBeVisible();const g=await image.evaluate(image=>{const n=image as HTMLImageElement,box=(p:Element)=>{const r=p.getBoundingClientRect();return{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height};},b=box(n),style=getComputedStyle(n),canvas=document.createElement('canvas');canvas.width=n.naturalWidth;canvas.height=n.naturalHeight;const ctx=canvas.getContext('2d')!;ctx.drawImage(n,0,0);const rgba=ctx.getImageData(0,0,canvas.width,canvas.height).data;let left=canvas.width,top=canvas.height,right=-1,bottom=-1,pixels=0;for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++)if(rgba[(y*canvas.width+x)*4+3]>16){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);pixels++;}const scale=Math.min(b.width/canvas.width,b.height/canvas.height),width=canvas.width*scale,height=canvas.height*scale,actual={left:b.left+(b.width-width)/2+left*scale,right:b.left+(b.width-width)/2+(right+1)*scale,top:b.top+(b.height-height)/2+top*scale,bottom:b.top+(b.height-height)/2+(bottom+1)*scale,width:(right-left+1)*scale,height:(bottom-top+1)*scale},parents=[] as any[];for(let p=n.parentElement;p;p=p.parentElement){const r=box(p),c=getComputedStyle(p);if(p.matches('.relic-form-surface,[data-testid=relic-inscription-object]')||/hidden|clip|auto|scroll/.test(c.overflow+c.overflowX+c.overflowY))parents.push({class:p.className,box:r,inside:actual.left>=r.left-.5&&actual.right<=r.right+.5&&actual.top>=r.top-.5&&actual.bottom<=r.bottom+.5});if(p.matches('[data-testid=relic-inscription-object]'))break;}return{source:n.currentSrc,complete:n.complete,naturalWidth:n.naturalWidth,naturalHeight:n.naturalHeight,alphaThreshold:16,alpha:{left,right,top,bottom,pixels,width:right-left+1,height:bottom-top+1},image:b,objectFit:style.objectFit,objectPosition:style.objectPosition,transform:style.transform,scale,actual,maxPaintedEdge:Math.max(actual.width,actual.height),parents};});await attach(info,'quota-sword-real-loaded-rgba16-contain-size',g);expect(g.complete).toBe(true);expect(g.naturalWidth).toBe(512);expect(g.naturalHeight).toBe(512);expect(g.objectFit).toBe('contain');expect(g.objectPosition).toBe('50% 50%');expect(g.transform).toBe('none');expect(g.alpha.pixels).toBeGreaterThan(0);expect(Number.isFinite(g.maxPaintedEdge)&&g.maxPaintedEdge>=80).toBe(true);expect(g.parents.some(r=>r.class==='relic-form-surface')).toBe(true);for(const parent of g.parents)expect(parent.inside,'Real alpha drawing inside '+parent.class).toBe(true);
}

async function tabTo(page:Page,id:string){const target=page.getByTestId(id);await page.keyboard.press('Tab');for(let i=0;i<20&&!await target.evaluate(n=>n===document.activeElement);i++)await page.keyboard.press('Tab');await expect(target).toBeFocused();}

async function focusPaint(page:Page,id:string,info:TestInfo,name:string){await layoutReady(page);const control=page.getByTestId(id);await expect(control).toBeFocused();const g=await control.evaluate(n=>{const box=(p:Element)=>{const r=p.getBoundingClientRect();return{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height};},inside=(a:any,b:any)=>a.left>=b.left-.5&&a.right<=b.right+.5&&a.top>=b.top-.5&&a.bottom<=b.bottom+.5,c=getComputedStyle(n),b=box(n),out=Math.max(0,parseFloat(c.outlineWidth)+parseFloat(c.outlineOffset)),paint={left:b.left-out,right:b.right+out,top:b.top-out,bottom:b.bottom+out},clips=[] as any[];for(let p=n.parentElement;p;p=p.parentElement){const style=getComputedStyle(p);if(/hidden|clip|auto|scroll/.test(style.overflow+style.overflowX+style.overflowY))clips.push({class:p.className,box:box(p),inside:inside(paint,box(p))});}const text=[] as any[];for(const p of document.querySelectorAll<HTMLElement>('dialog[open] button,dialog[open] h3,dialog[open] p,dialog[open] strong,dialog[open] small')){if(p===n||n.contains(p)||p.contains(n)||!p.getClientRects().length)continue;const r=document.createRange();r.selectNodeContents(p);for(const row of r.getClientRects())if(row.width&&row.height){const b={left:row.left,right:row.right,top:row.top,bottom:row.bottom};text.push({text:p.textContent,box:b,collision:paint.left<b.right&&paint.right>b.left&&paint.top<b.bottom&&paint.bottom>b.top});}}return{outline:c.outlineStyle,outlineWidth:parseFloat(c.outlineWidth),outlineOffset:parseFloat(c.outlineOffset),b,paint,clips,text,viewport:inside(paint,{left:0,right:innerWidth,top:0,bottom:innerHeight})};});await attach(info,name+'-actual-focus-paint-and-text-ranges',g);expect(g.outline).not.toBe('none');expect(g.outlineWidth).toBeGreaterThan(0);expect(g.viewport).toBe(true);for(const clip of g.clips)expect(clip.inside,clip.class).toBe(true);expect(g.text.filter(r=>r.collision)).toEqual([]);}

test('ART10-A9 catalogue preparation and limit surfaces keep one keyboard owner complete text and the selected object on close',async({page},info)=>{
 const before=await load(page,goldenFixture()),raw=await database(page);await skills(page,'sword_guard');for(const [open,dialog,close]of [['learning-library-open','learning-library-dialog','learning-library-close'],['learning-plan-open','learning-plan-dialog','learning-plan-close']]){await readonlyClick(page,open);await expect(page.getByTestId(dialog)).toBeVisible();await expect(page.locator('dialog[open]')).toHaveCount(1);if(dialog==='learning-library-dialog')await librarySpines(page,info);await tabTo(page,close);await focusPaint(page,close,info,dialog+'-keyboard-focus');await frame(page,info,dialog+'-complete-keyboard-surface');await page.keyboard.press('Escape');await expect(page.getByTestId(dialog)).not.toBeVisible();await expect(page.getByTestId(open)).toBeFocused();await readonlyState(page,before,raw);}await expect(page.getByTestId('jade-engraving')).toHaveAttribute('data-skill','sword_guard');await relic(page,'jade_seal');for(const [open,dialog,close]of [['relic-library-open','relic-library-dialog','relic-library-close'],['relic-preparation-open','relic-preparation-dialog','relic-preparation-close']]){await readonlyClick(page,open);await expect(page.getByTestId(dialog)).toBeVisible();await expect(page.locator('dialog[open]')).toHaveCount(1);if(dialog==='learning-library-dialog')await librarySpines(page,info);await tabTo(page,close);await focusPaint(page,close,info,dialog+'-keyboard-focus');await frame(page,info,dialog+'-complete-keyboard-surface');await page.keyboard.press('Escape');await expect(page.getByTestId(dialog)).not.toBeVisible();await expect(page.getByTestId(open)).toBeFocused();await readonlyState(page,before,raw);}await readonlyClick(page,'relic-preparation-open');await readonlyClick(page,'relic-preparation-limits');await expect(page.getByTestId('relic-preparation-dialog')).not.toBeVisible();await expect(page.getByRole('dialog')).toContainText('投入限额');await expect(page.locator('dialog[open]')).toHaveCount(1);await frame(page,info,'preparation-to-full-limits-is-one-real-surface');await page.getByRole('button',{name:'取消调整',exact:true}).click();await expect(page.locator('dialog[open]')).toHaveCount(0);await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-relic','jade_seal');await readonlyState(page,before,raw);await noArrival(page);
});
